/* eslint-disable @typescript-eslint/no-explicit-any */
<script setup lang="ts">
import { ref, watch } from "vue";
import { useI18n } from "vue-i18n";

const { t } = useI18n();

const props = defineProps<{
  modelValue: boolean;
  initialPath?: string;
}>();

const emit = defineEmits<{
  (e: "update:modelValue", val: boolean): void;
  (e: "select", path: string): void;
}>();

const currentPath = ref("");
const inputPath = ref("");
const parentPath = ref<string | null>(null);
const folders = ref<string[]>([]);
const selectedFolder = ref<string | null>(null);

const isLoading = ref(false);
const errorMsg = ref("");

// Watch visibility
watch(
  () => props.modelValue,
  (isOpen) => {
    if (isOpen) {
      selectedFolder.value = null;
      loadDirectory(props.initialPath || currentPath.value || "");
    }
  },
);

async function loadDirectory(pathStr: string) {
  isLoading.value = true;
  errorMsg.value = "";
  try {
    const res = await $fetch<{
      currentPath: string;
      parentPath: string | null;
      folders: string[];
    }>("/api/utils/list-dir", {
      query: { path: pathStr },
    });
    currentPath.value = res.currentPath;
    inputPath.value = res.currentPath;
    parentPath.value = res.parentPath;
    folders.value = res.folders;
    selectedFolder.value = null;
  } catch (err: any) {
    errorMsg.value =
      err.data?.statusMessage ||
      err.message ||
      t("folderPicker.cannotAccessFolder");
  } finally {
    isLoading.value = false;
  }
}

function selectFolder(folder: string) {
  selectedFolder.value = folder;
  // Auto-fill the input path to show the full combined path
  inputPath.value = currentPath.value.replace(/[\\/]$/, "") + "\\" + folder;
}

function navigateToFolder(folder: string) {
  const newPath = currentPath.value.replace(/[\\/]$/, "") + "\\" + folder;
  loadDirectory(newPath);
}

function navigateTo(pathStr: string) {
  loadDirectory(pathStr);
}

function goUp() {
  if (parentPath.value) {
    loadDirectory(parentPath.value);
  }
}

function close() {
  emit("update:modelValue", false);
}

function confirm() {
  // If a folder is selected in the list, use that path.
  // Otherwise, use the current viewed path (inputPath).
  emit("select", inputPath.value || currentPath.value);
  close();
}
</script>

<template>
  <Transition name="fade">
    <div
      v-if="modelValue"
      class="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/40 backdrop-blur-sm p-4"
    >
      <div
        class="bg-white rounded-2xl shadow-2xl w-full max-w-2xl overflow-hidden flex flex-col transform transition-all border border-slate-200"
        @click.stop
      >
        <!-- Header -->
        <div
          class="px-5 py-4 border-b border-slate-100 flex items-center justify-between bg-slate-50"
        >
          <div class="flex items-center gap-3">
            <div
              class="w-8 h-8 rounded-full bg-amnimo-100 text-amnimo-600 flex items-center justify-center"
            >
              <Icon name="heroicons:folder-open" class="w-4 h-4" />
            </div>
            <div>
              <h3 class="font-bold text-slate-800">
                {{ $t("folderPicker.selectFolder") }}
              </h3>
              <p
                class="text-xs text-slate-500 font-mono mt-0.5 truncate max-w-sm"
                :title="currentPath"
              >
                {{ currentPath }}
              </p>
            </div>
          </div>
          <button
            class="p-2 text-slate-400 hover:text-slate-600 hover:bg-slate-100 rounded-lg transition-colors"
            @click="close"
          >
            <Icon name="heroicons:x-mark" class="w-5 h-5" />
          </button>
        </div>

        <!-- Path Breadcrumb / Input -->
        <div class="px-5 py-3 border-b border-slate-100 flex gap-2">
          <button
            :disabled="!parentPath"
            class="px-3 py-1.5 border border-slate-200 rounded-lg text-slate-600 hover:bg-slate-50 disabled:opacity-50 disabled:bg-slate-50 flex items-center gap-1 shrink-0"
            :title="$t('folderPicker.goUpOneLevel')"
            @click="goUp"
          >
            <Icon name="heroicons:arrow-up" class="w-4 h-4" />
          </button>
          <input
            v-model="inputPath"
            type="text"
            class="flex-1 px-3 py-1.5 border border-slate-200 rounded-lg text-sm font-mono focus:ring-amnimo-500 focus:border-amnimo-500"
            :placeholder="$t('folderPicker.enterPathManually')"
            @keyup.enter="navigateTo(inputPath)"
          >
          <button
            class="px-3 py-1.5 bg-slate-100 text-slate-700 hover:bg-slate-200 rounded-lg font-bold text-sm shrink-0"
            @click="navigateTo(inputPath)"
          >
            {{ $t("folderPicker.go") }}
          </button>
        </div>

        <!-- Folder List -->
        <div class="flex-1 h-[40vh] min-h-[300px] overflow-y-auto p-2 bg-white">
          <div
            v-if="isLoading"
            class="h-full flex items-center justify-center text-slate-400 gap-2"
          >
            <AppSpinner size="sm" /> {{ $t("folderPicker.loading") }}
          </div>
          <div
            v-else-if="errorMsg"
            class="h-full flex items-center justify-center text-rose-500 gap-2 px-6 text-center"
          >
            <Icon
              name="heroicons:exclamation-circle"
              class="w-5 h-5 shrink-0"
            />
            <span class="text-sm font-medium">{{ errorMsg }}</span>
          </div>
          <div
            v-else-if="folders.length === 0"
            class="h-full flex items-center justify-center text-slate-400 text-sm"
          >
            {{ $t("folderPicker.folderEmpty") }}
          </div>
          <div v-else class="grid grid-cols-1 sm:grid-cols-2 gap-1">
            <button
              v-for="folder in folders"
              :key="folder"
              class="flex items-center gap-3 px-3 py-2 rounded-lg text-left transition-colors group"
              :class="
                selectedFolder === folder
                  ? 'bg-amnimo-50 text-amnimo-900 ring-1 ring-amnimo-200'
                  : 'hover:bg-slate-50 text-slate-700'
              "
              @click="selectFolder(folder)"
              @dblclick="navigateToFolder(folder)"
            >
              <Icon
                :name="
                  selectedFolder === folder
                    ? 'heroicons:folder-open'
                    : 'heroicons:folder'
                "
                class="w-5 h-5 shrink-0 transition-colors"
                :class="
                  selectedFolder === folder
                    ? 'text-amnimo-500'
                    : 'text-slate-400 group-hover:text-amber-400'
                "
              />
              <span class="text-sm truncate select-none">{{ folder }}</span>
            </button>
          </div>
        </div>

        <!-- Footer -->
        <div
          class="px-5 py-4 border-t border-slate-100 bg-slate-50 flex items-center justify-between"
        >
          <div class="text-xs text-slate-500 flex items-center gap-1.5">
            <Icon name="heroicons:information-circle" class="w-4 h-4" />
            {{ $t("folderPicker.clickHint") }}
          </div>
          <div class="flex gap-3">
            <button
              class="px-4 py-2 rounded-xl text-slate-600 hover:bg-slate-200 font-bold text-sm transition-colors"
              @click="close"
            >
              {{ $t("folderPicker.cancel") }}
            </button>
            <button
              class="px-5 py-2 rounded-xl bg-amnimo-600 text-white hover:bg-amnimo-700 font-bold text-sm shadow-sm transition-all shadow-amnimo-200"
              @click="confirm"
            >
              {{ $t("folderPicker.selectFolder") }}
            </button>
          </div>
        </div>
      </div>
    </div>
  </Transition>
</template>

<style scoped>
.fade-enter-active,
.fade-leave-active {
  transition: opacity 0.2s ease;
}

.fade-enter-from,
.fade-leave-to {
  opacity: 0;
}

.fade-enter-active > div {
  transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

.fade-enter-from > div {
  transform: scale(0.95) translateY(10px);
}
</style>

/* eslint-disable @typescript-eslint/no-explicit-any */
<script setup lang="ts">
import { ref, watch, computed } from "vue";
import { useI18n } from "vue-i18n";
import { useToast } from "~/composables/useToast";
import { useRouter } from "vue-router";

const { t } = useI18n();
const { addToast } = useToast();


const router = useRouter();

const props = defineProps<{
  modelValue: boolean;
  sessionId: string;
}>();

const emit = defineEmits(["update:modelValue"]);

type ReportData = {
  id: string;
  name: string;
  createdAt: string;
  excelJsonUrl?: string;
  htmlReportUrl?: string;
  failedCount?: number;
  passedCount?: number;
  totalCount?: number;
};

const isLoading = ref(false);
const reports = ref<ReportData[]>([]);

const isJsonViewerOpen = ref(false);
const activeJsonUrl = ref("");

const openJsonViewer = (url: string) => {
  activeJsonUrl.value = url;
  isJsonViewerOpen.value = true;
};

const isHtmlViewerOpen = ref(false);
const activeHtmlUrl = ref("");

const openHtmlViewer = (url: string) => {
  activeHtmlUrl.value = url;
  isHtmlViewerOpen.value = true;
};

const fetchReports = async () => {
  if (props.sessionId) {
    isLoading.value = true;
    try {
      reports.value = await $fetch<ReportData[]>(
        `/api/sessions/${props.sessionId}/reports`,
      );
    } catch (e: any) {
      console.error("Failed to load reports", e);
      reports.value = [];
    } finally {
      isLoading.value = false;
    }
  }
};

watch(
  () => props.modelValue,
  (isOpen) => {
    if (isOpen) {
      fetchReports();
    }
  },
);

const isRerunning = ref(false);

const rerunFailedTests = async (reportName: string) => {
  if (!props.sessionId || isRerunning.value) return;
  isRerunning.value = true;
  try {
    await $fetch("/api/tests/run", {
      method: "POST",
      body: {
        sessionId: props.sessionId,
        testType: "release",
        mode: "rerun-failed",
        sessionName: reportName,
      },
    });
    emit("update:modelValue", false);
    router.push(`/sessions/${props.sessionId}/runner`);
  } catch (e: any) {
    addToast({
      title: t("reportModal.error"),
      message: t("reportModal.failedToRerun") + e.message,
      type: "error",
    });
  } finally {
    isRerunning.value = false;
  }
};

const reportToDelete = ref<ReportData | null>(null);
const isDeleting = ref(false);

const confirmDeleteReport = async () => {
  if (!reportToDelete.value || isDeleting.value) return;
  isDeleting.value = true;
  try {
    await $fetch("/api/reports/delete", {
      method: "POST",
      body: { reportId: reportToDelete.value.id },
    });
    // Successfully deleted, refresh list
    await fetchReports();
  } catch (e: any) {
    addToast({
      title: t("reportModal.error"),
      message:
        t("reportModal.failedToDelete") + (e.data?.statusMessage || e.message),
      type: "error",
    });
  } finally {
    isDeleting.value = false;
    reportToDelete.value = null;
  }
};
</script>

<template>
  <Transition name="modal">
    <div
      v-if="modelValue"
      class="fixed inset-0 z-[60] flex items-center justify-center p-4"
    >
      <div
        class="modal-backdrop fixed inset-0 bg-slate-900/60 backdrop-blur-sm transform-gpu will-change-opacity"
        @click="$emit('update:modelValue', false)"
      />
      <div
        class="modal-content relative bg-white rounded-2xl shadow-glass w-full max-w-4xl max-h-[85vh] flex flex-col overflow-hidden"
      >
        <div
          class="px-8 py-5 border-b border-slate-100 flex justify-between items-center bg-white shrink-0"
        >
          <h3 class="text-xl font-bold text-slate-900 flex items-center gap-2">
            <Icon
              name="heroicons:document-chart-bar"
              class="w-6 h-6 text-amnimo-500"
            />
            {{ $t("reportModal.testReports") }}
          </h3>
          <div class="flex items-center gap-3">
            <button
              class="text-slate-400 hover:text-amnimo-600 bg-slate-50 hover:bg-amnimo-50 p-2 rounded-xl transition-colors"
              @click="$emit('update:modelValue', false)"
            >
              <Icon name="heroicons:x-mark" class="w-5 h-5" />
            </button>
          </div>
        </div>

        <div
          class="p-8 overflow-y-auto flex-1 bg-slate-50/50 min-h-[300px] custom-scrollbar"
        >
          <div
            v-if="isLoading"
            class="flex flex-col items-center justify-center h-full text-amnimo-400 gap-4"
          >
            <AppLoader size="md" :text="$t('reportModal.loadingReport')" />
            <span class="font-bold text-slate-600">{{
              $t("reportModal.searchingForReports")
            }}</span>
          </div>

          <div
            v-else-if="reports.length === 0"
            class="flex flex-col items-center justify-center h-full text-slate-400 gap-4"
          >
            <div
              class="w-20 h-20 bg-white rounded-full flex items-center justify-center shadow-sm border border-slate-100"
            >
              <Icon name="heroicons:inbox" class="w-10 h-10 text-slate-300" />
            </div>
            <p class="font-bold text-slate-800 text-lg">
              {{ $t("reportModal.noReportsFound") }}
            </p>
            <p
              class="text-sm font-medium text-slate-500 text-center max-w-sm leading-relaxed"
            >
              {{ $t("reportModal.reportsGeneratedAuto") }}
            </p>
          </div>

          <div v-else class="space-y-4">
            <div
              v-for="report in reports"
              :key="report.id"
              class="bg-white border border-slate-200 hover:border-amnimo-300 rounded-2xl p-5 flex flex-col sm:flex-row sm:items-center justify-between gap-4 transition-all duration-300 shadow-sm hover:shadow-soft group"
            >
              <div>
                <h4
                  class="font-bold text-slate-900 flex items-center gap-2 text-lg group-hover:text-amnimo-700 transition-colors"
                >
                  <Icon
                    name="heroicons:folder-open"
                    class="w-5 h-5 text-amnimo-400"
                  />
                  {{ report.name }}
                </h4>
                <div class="flex items-center gap-3 mt-1.5 pl-7">
                  <p
                    class="text-sm font-medium text-slate-600 flex items-center gap-1.5"
                  >
                    <Icon
                      name="heroicons:clock"
                      class="w-4 h-4 text-slate-400"
                    />
                    {{ new Date(report.createdAt).toLocaleString() }}
                  </p>

                  <!-- Status Badges -->
                  <div
                    v-if="report.totalCount !== undefined"
                    class="flex gap-2"
                  >
                    <span
                      v-if="report.failedCount && report.failedCount > 0"
                      class="inline-flex items-center gap-1 px-2 py-0.5 rounded-md bg-rose-50 text-rose-700 text-xs font-bold border border-rose-200"
                    >
                      <Icon name="heroicons:x-circle" class="w-3.5 h-3.5" />
                      {{ report.failedCount }} {{ $t("reportModal.failed") }}
                    </span>
                    <span
                      v-else-if="
                        report.totalCount > 0 && report.failedCount === 0
                      "
                      class="inline-flex items-center gap-1 px-2 py-0.5 rounded-md bg-emerald-50 text-emerald-700 text-xs font-bold border border-emerald-200"
                    >
                      <Icon name="heroicons:check-circle" class="w-3.5 h-3.5" />
                      {{ $t("reportModal.allPassed") }} ({{
                        report.totalCount
                      }})
                    </span>
                  </div>
                </div>
              </div>
              <div class="flex flex-wrap gap-3 sm:shrink-0">
                <button
                  v-if="report.failedCount && report.failedCount > 0"
                  :disabled="isRerunning"
                  class="inline-flex items-center gap-2 px-4 py-2 text-sm font-bold text-amber-700 bg-amber-50 border border-amber-200 rounded-xl hover:bg-amber-100 hover:text-amber-800 transition-colors shadow-sm active:scale-95 disabled:opacity-50"
                  @click="rerunFailedTests(report.name)"
                >
                  <Icon
                    v-if="isRerunning"
                    name="heroicons:arrow-path"
                    class="w-5 h-5 animate-spin"
                  />
                  <Icon
                    v-else
                    name="heroicons:arrow-path-rounded-square"
                    class="w-5 h-5"
                  />
                  {{ $t("reportModal.rerunFailed") }}
                </button>
                <button
                  v-if="report.htmlReportUrl"
                  class="inline-flex items-center gap-2 px-4 py-2 text-sm font-bold text-slate-800 bg-white border border-slate-300 rounded-xl hover:bg-slate-50 hover:text-amnimo-600 transition-colors shadow-sm active:scale-95"
                  @click="openHtmlViewer(report.htmlReportUrl)"
                >
                  <Icon name="heroicons:chart-bar-square" class="w-5 h-5" />
                  {{ $t("reportModal.htmlReport") }}
                </button>
                <button
                  v-if="report.excelJsonUrl"
                  class="inline-flex items-center gap-2 px-4 py-2 text-sm font-bold text-white bg-amnimo-600 border border-transparent rounded-xl hover:bg-amnimo-700 transition-colors shadow-sm hover:shadow-lg hover:shadow-amnimo-500/30 active:scale-95"
                  @click="openJsonViewer(report.excelJsonUrl)"
                >
                  <Icon name="heroicons:table-cells" class="w-5 h-5" />
                  {{ $t("reportModal.viewData") }}
                </button>
                <button
                  class="inline-flex items-center justify-center w-9 h-9 text-slate-400 bg-white border border-slate-200 rounded-xl hover:bg-rose-50 hover:text-rose-600 hover:border-rose-200 transition-colors shadow-sm active:scale-95"
                  :title="$t('reportModal.deleteReportTitle')"
                  @click="reportToDelete = report"
                >
                  <Icon name="heroicons:trash" class="w-4 h-4" />
                </button>
              </div>
            </div>
          </div>
        </div>

        <!-- Delete Confirmation Modal -->
        <Transition name="modal">
          <div
            v-if="reportToDelete"
            class="absolute inset-0 z-[70] flex items-center justify-center p-4"
          >
            <div
              class="absolute inset-0 bg-slate-900/40 backdrop-blur-sm rounded-2xl"
              @click="reportToDelete = null"
            />
            <div
              class="relative bg-white border border-slate-200 shadow-xl rounded-2xl p-6 max-w-sm w-full mx-4 text-center transform transition-all"
            >
              <div
                class="w-16 h-16 bg-rose-50 text-rose-500 rounded-full flex items-center justify-center mx-auto mb-4 border border-rose-100"
              >
                <Icon name="heroicons:exclamation-triangle" class="w-8 h-8" />
              </div>
              <h4 class="text-lg font-bold text-slate-900 mb-2">
                {{ $t("reportModal.deleteReportConfirmTitle") }}
              </h4>
              <p class="text-sm text-slate-500 mb-6 leading-relaxed">
                {{ $t("reportModal.deleteReportConfirmText1") }}
                <b class="text-slate-700">{{ reportToDelete.name }}</b
                >{{ $t("reportModal.deleteReportConfirmText2") }}
              </p>
              <div class="flex gap-3 justify-center">
                <button
                  class="px-5 py-2 text-sm font-bold text-slate-600 bg-slate-100 hover:bg-slate-200 rounded-xl transition-colors active:scale-95"
                  @click="reportToDelete = null"
                >
                  {{ $t("reportModal.cancel") }}
                </button>
                <button
                  :disabled="isDeleting"
                  class="inline-flex items-center justify-center gap-2 px-5 py-2 text-sm font-bold text-white bg-rose-600 hover:bg-rose-700 rounded-xl transition-colors shadow-sm active:scale-95 disabled:opacity-50"
                  @click="confirmDeleteReport"
                >
                  <Icon
                    v-if="isDeleting"
                    name="heroicons:arrow-path"
                    class="w-4 h-4 animate-spin"
                  />
                  <Icon v-else name="heroicons:trash" class="w-4 h-4" />
                  {{ $t("reportModal.delete") }}
                </button>
              </div>
            </div>
          </div>
        </Transition>
      </div>

      <ExcelJsonViewer v-model="isJsonViewerOpen" :json-url="activeJsonUrl" />
      <HtmlReportViewer v-model="isHtmlViewerOpen" :url="activeHtmlUrl" />
    </div>
  </Transition>
</template>

/* eslint-disable @typescript-eslint/no-explicit-any */
<template>
  <Transition name="slide-up">
    <div
      v-if="isVisible"
      class="fixed bottom-6 right-6 z-[10000] bg-white rounded-2xl shadow-xl border border-slate-200 p-5 max-w-sm w-full flex flex-col gap-3"
    >
      <div class="flex items-start gap-3">
        <div class="shrink-0 pt-0.5">
          <Icon
            name="heroicons:arrow-path-rounded-square"
            class="w-6 h-6 text-amnimo-500"
            :class="{
              'animate-spin': status === 'checking' || status === 'downloading',
            }"
          />
        </div>

        <div class="flex-1 flex flex-col gap-1 min-w-0">
          <h4 class="text-base font-bold text-slate-800">{{ title }}</h4>
          <p class="text-sm text-slate-500 leading-snug">{{ message }}</p>

          <div
            v-if="status === 'downloading'"
            class="mt-2 h-2 w-full bg-slate-100 rounded-full overflow-hidden"
          >
            <div
              class="h-full bg-amnimo-500 transition-all duration-300"
              :style="{ width: `${progress}%` }"
            ></div>
          </div>
        </div>

        <button
          v-if="status === 'not-available' || status === 'error'"
          @click="close"
          class="shrink-0 p-1 text-slate-400 hover:text-slate-600 hover:bg-slate-50 rounded-lg transition-colors -mr-2 -mt-2"
        >
          <Icon name="heroicons:x-mark" class="w-5 h-5" />
        </button>
      </div>

      <div v-if="status === 'downloaded'" class="flex justify-end gap-2 mt-2">
        <button
          @click="close"
          class="px-4 py-2 text-sm font-bold text-slate-600 bg-slate-100 hover:bg-slate-200 rounded-lg transition-colors"
        >
          {{ $t("updateNotifier.later") }}
        </button>
        <button
          @click="installUpdate"
          class="px-4 py-2 text-sm font-bold text-white bg-amnimo-600 hover:bg-amnimo-700 rounded-lg transition-colors"
        >
          {{ $t("updateNotifier.restartAndInstall") }}
        </button>
      </div>
    </div>
  </Transition>
</template>

<script setup lang="ts">
import { ref, onMounted, onUnmounted, computed } from "vue";
import { useI18n } from "vue-i18n";

const { t } = useI18n();

const isVisible = ref(false);
const status = ref<
  | "checking"
  | "available"
  | "not-available"
  | "downloading"
  | "downloaded"
  | "error"
  | ""
>("");
const progress = ref(0);
const versionInfo = ref("");
const errorMessage = ref("");

const title = computed(() => {
  switch (status.value) {
    case "checking":
      return t("updateNotifier.checkingForUpdates");
    case "available":
      return t("updateNotifier.updateAvailable");
    case "downloading":
      return t("updateNotifier.downloadingUpdate");
    case "downloaded":
      return t("updateNotifier.readyToInstall");
    case "not-available":
      return t("updateNotifier.upToDate");
    case "error":
      return t("updateNotifier.updateFailed");
    default:
      return t("updateNotifier.update");
  }
});

const message = computed(() => {
  switch (status.value) {
    case "checking":
      return t("updateNotifier.msgChecking");
    case "available":
      return t("updateNotifier.msgAvailable", { version: versionInfo.value });
    case "downloading":
      return t("updateNotifier.msgDownloading", {
        progress: Math.round(progress.value),
      });
    case "downloaded":
      return t("updateNotifier.msgDownloaded", { version: versionInfo.value });
    case "not-available":
      return t("updateNotifier.msgNotAvailable");
    case "error":
      return errorMessage.value || t("updateNotifier.msgError");
    default:
      return "";
  }
});

onMounted(() => {
  if (typeof window !== "undefined" && (window as any).electronAPI) {
    (window as any).electronAPI.onUpdateStatus((updateStatus: any) => {
      isVisible.value = true;
      status.value = updateStatus.status;

      if (updateStatus.version) {
        versionInfo.value = updateStatus.version;
      }
      if (updateStatus.percent) {
        progress.value = updateStatus.percent;
      }
      if (updateStatus.error) {
        errorMessage.value = updateStatus.error;
      }

      // Auto-hide if no update
      if (status.value === "not-available") {
        setTimeout(() => close(), 4000);
      }
    });

    // Automatically check for updates on startup
    setTimeout(() => {
      (window as any).electronAPI.checkForUpdates();
    }, 5000);
  }
});

onUnmounted(() => {
  if (typeof window !== "undefined" && (window as any).electronAPI) {
    (window as any).electronAPI.removeUpdateStatusListener();
  }
});

const close = () => {
  isVisible.value = false;
};

const installUpdate = () => {
  if (typeof window !== "undefined" && (window as any).electronAPI) {
    (window as any).electronAPI.installUpdate();
  }
};
</script>

<style scoped>
.slide-up-enter-active,
.slide-up-leave-active {
