          </div>
          <div class="flex justify-between items-center">
            <span class="text-slate-500 font-medium">{{
              $t("peripheralPoeCheck.state")
            }}</span>
            <span
              class="font-bold font-mono px-2 py-0.5 rounded text-xs"
              :class="
