            <div class="flex justify-between items-center">
              <span class="text-slate-500 font-medium">{{
                $t("peripheralPoeCheck.current")
              }}</span>
              <span class="font-bold text-slate-800 font-mono"
                >{{ poeInfo.current?.toFixed(2) }} mA</span
              >
            </div>
