const password = ref("yoko1234");

const simInfo = ref<any>(null);

onMounted(() => {
  if (props.baseUrl) {
    checkSim();
  }
});

// Reset state if un-checked manually via other means
watch(
  () => props.modelValue,
  (newVal) => {
    if (!newVal) {
      simInfo.value = null;
      errorMsg.value = "";
      needsLogin.value = false;
    }
  },
);

async function checkSim() {
  if (!props.baseUrl) {
    errorMsg.value = t("peripheralSimCheck.errorNoUrl");
    return;
