/* eslint-disable @typescript-eslint/no-explicit-any */
import { ref, computed } from 'vue';
import { useI18n } from 'vue-i18n';

export interface Firmware {
  filename: string;
  source: string;
  board: string;
  version: string;
  build: string;
  isModem: boolean;
  date: string;
  size: number;
  url: string;
}

export function useFirmwareManager() {
  const { t } = useI18n();

  const firmwares = ref<Firmware[]>([]);
  const isLoading = ref(false);
  const error = ref("");

  const selectedSource = ref<string | null>(null);
  const searchQuery = ref("");
  const filterBoard = ref("all");
  const sortKey = ref<keyof Firmware>("date");
  const sortOrder = ref<"asc" | "desc">("desc");

  const isBoardDropdownOpen = ref(false);
  const BOARD_LIST = [
    "AG10", "AG20", "AX11", "AX12", "AX21", "AX30", "AR10", "AR20", "AC10", "AC15", "AC25",
  ];

  const sortBy = (key: keyof Firmware) => {
    if (sortKey.value === key) {
      sortOrder.value = sortOrder.value === "asc" ? "desc" : "asc";
    } else {
      sortKey.value = key;
      sortOrder.value = key === "date" ? "desc" : "asc";
    }
  };

  const selectBoardFilter = (board: string) => {
    filterBoard.value = board;
    isBoardDropdownOpen.value = false;
  };

  const filteredFirmwares = computed(() => {
    if (!selectedSource.value) return [];

    let result = firmwares.value.filter((fw) => {
      if (fw.source !== selectedSource.value) return false;
      if (searchQuery.value) {
        const query = searchQuery.value.toLowerCase();
        if (!fw.filename.toLowerCase().includes(query)) return false;
      }
      if (filterBoard.value !== "all") {
        const boardParts = fw.board.split("_");
        if (!boardParts.includes(filterBoard.value)) return false;
      }
      return true;
    });

    result.sort((a, b) => {
      let valA: any = a[sortKey.value];
      let valB: any = b[sortKey.value];

      if (sortKey.value === "date") {
        (valA as any) = new Date(a.date).getTime();
        (valB as any) = new Date(b.date).getTime();
      } else if (sortKey.value === "version") {
        const collator = new Intl.Collator(undefined, { numeric: true, sensitivity: "base" });
        return sortOrder.value === "asc" ? collator.compare((valA as any), (valB as any)) : collator.compare((valB as any), (valA as any));
      } else if (typeof (valA as any) === "string") {
        (valA as any) = (valA as any).toLowerCase();
        (valB as any) = ((valB as any) as string).toLowerCase();
      }

      if ((valA as any) < (valB as any)) return sortOrder.value === "asc" ? -1 : 1;
      if ((valA as any) > (valB as any)) return sortOrder.value === "asc" ? 1 : -1;
      return 0;
    });

    return result;
  });

  const selectSource = (source: string) => {
    selectedSource.value = source;
    searchQuery.value = "";
    filterBoard.value = "all";
  };

  const clearSource = () => {
    selectedSource.value = null;
  };

  const fetchFirmwares = async () => {
    isLoading.value = true;
    error.value = "";
    try {
      firmwares.value = await $fetch<Firmware[]>("/api/firmwares/external");
    } catch (err: any) {
      console.error("Failed to fetch firmwares", err);
      error.value = t("firmware.fetchError");
    } finally {
      isLoading.value = false;
    }
  };

  const formatBytes = (bytes: number, decimals = 2) => {
    if (!+bytes) return "0 Bytes";
    const k = 1024;
    const dm = decimals < 0 ? 0 : decimals;
    const sizes = ["Bytes", "KB", "MB", "GB", "TB"];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return `${parseFloat((bytes / Math.pow(k, i)).toFixed(dm))} ${sizes[i]}`;
  };

  return {
    firmwares,
    isLoading,
    error,
    selectedSource,
    searchQuery,
    filterBoard,
    sortKey,
    sortOrder,
    isBoardDropdownOpen,
    BOARD_LIST,
    sortBy,
    selectBoardFilter,
    filteredFirmwares,
    selectSource,
    clearSource,
    fetchFirmwares,
    formatBytes
  };
}

/* eslint-disable @typescript-eslint/no-explicit-any */
/* eslint-disable @typescript-eslint/no-explicit-any */
import { ref, computed } from 'vue';

export function useNetworkCheck(baseUrlRef: { value: string }) {
  const pingStatus = ref<"idle" | "pinging" | "success" | "failed">("idle");
  const isPinging = computed(() => pingStatus.value === "pinging");
  let pingInterval: any = null;

  const pingDevice = async (silent = false) => {
    if (!silent) pingStatus.value = "pinging";
    try {
      const ipMatch = baseUrlRef.value.match(/https?:\/\/([^:]+)/);
      const ip = ipMatch ? ipMatch[1] : baseUrlRef.value;

      const res = await $fetch<{ success: boolean }>("/api/network/ping", {
        method: "POST",
        body: { ip },
      });

      if (res.success) {
        if (pingStatus.value !== "success") {
          try {
            await $fetch("/api/proxy/device/startup-check", {
              method: "POST",
              body: {
                targetUrl: baseUrlRef.value,
                defaultPassword: "yoko1234",
              },
            });
          } catch (startupErr) {
            console.warn("Startup check failed or not applicable:", startupErr);
          }
        }
        pingStatus.value = "success";
      } else {
        pingStatus.value = "failed";
      }
    } catch (err) {
      pingStatus.value = "failed";
    }
  };

  const startPingPolling = () => {
    stopPingPolling();
    pingDevice(pingStatus.value !== "idle"); // If idle, show loading, otherwise silent
    pingInterval = setInterval(() => {
      pingDevice(true);
    }, 3000);
  };

  const stopPingPolling = () => {
    if (pingInterval) {
      clearInterval(pingInterval);
      pingInterval = null;
    }
  };

  const resetPingStatus = () => {
    pingStatus.value = "idle";
  };

  return {
    pingStatus,
    isPinging,
    pingDevice,
    startPingPolling,
    stopPingPolling,
    resetPingStatus
  };
}

