import { $fetch } from "ofetch";

export default defineEventHandler(async (event) => {
  const body = await readBody(event);
  const { targetUrl, username, password } = body;

  const urlStr = targetUrl.startsWith("http")
    ? targetUrl
    : `https://${targetUrl}`;

  // Temporarily bypass self-signed cert errors for the proxy request
  const originalTlsConfig = process.env.NODE_TLS_REJECT_UNAUTHORIZED;
  process.env.NODE_TLS_REJECT_UNAUTHORIZED = "0";

  try {
    const authHeaders: Record<string, string> = {
      Accept: "application/json",
      Authorization:
        "Basic " + Buffer.from(`${username}:${password}`).toString("base64"),
    };

    // First try to login to get token/cookie if Basic Auth isn't enough
    try {
      const authRes = await $fetch.raw(`${urlStr}/api/auth`, {
        method: "POST",
        body: { username, password },
        headers: { "Content-Type": "application/json" },
        timeout: 10000,
      });

      const setCookie = authRes.headers.get("set-cookie");
      if (setCookie) {
        authHeaders["Cookie"] = setCookie;
      }

      const authData: any = authRes._data;
      if (authData && authData.token) {
        authHeaders["Authorization"] = `Bearer ${authData.token}`;
      }
    } catch (e) {
      // Ignore auth failure, fallback to Basic auth
    }

    // Try fetching network config to check DHCP
    let br0Config: any = null;
    let hasDhcpEnabled = false;

    const res: any = await $fetch(`${urlStr}/api/configs/interfaces`, {
      method: "GET",
      headers: authHeaders,
      timeout: 10000,
    });

    // Look for br0 and check dhcp4.enabled
    const interfaces = res?.content?.interfaces || [];
    for (const iface of interfaces) {
      if (iface.name === "br0") {
        br0Config = iface;
        if (iface.dhcp4?.enabled === true) {
          hasDhcpEnabled = true;
        }
        break;
      }
    }

    if (br0Config && hasDhcpEnabled) {
      return {
        success: true,
        message: "DHCP Client is enabled on br0 of the Partner GW",
        config: br0Config,
      };
    } else if (br0Config) {
      return {
        success: false,
        message: "Interface br0 is found but DHCP Client is NOT enabled on it.",
        config: br0Config,
      };
    } else {
      return {
        success: false,
        message: "Interface br0 could not be found on the Partner GW.",
      };
    }
  } catch (err: any) {
    if (err.status === 401) {
      throw createError({
        statusCode: 401,
        statusMessage:
          "Unauthorized to access Partner GW. Please check credentials.",
      });
    }
    throw createError({
      statusCode: 500,
      statusMessage: err.message || "Failed to communicate with Partner GW API",
    });
  } finally {
    if (originalTlsConfig !== undefined) {
      process.env.NODE_TLS_REJECT_UNAUTHORIZED = originalTlsConfig;
    } else {
      delete process.env.NODE_TLS_REJECT_UNAUTHORIZED;
    }
  }
});

import { $fetch } from "ofetch";

export default defineEventHandler(async (event) => {
  const body = await readBody(event);
  const { baseUrl, username, password } = body;

  // Ensure url uses https
  const urlStr = baseUrl.startsWith("http") ? baseUrl : `https://${baseUrl}`;

  // Temporarily bypass self-signed cert errors for the proxy request
  const originalTlsConfig = process.env.NODE_TLS_REJECT_UNAUTHORIZED;
  process.env.NODE_TLS_REJECT_UNAUTHORIZED = "0";

  try {
    let authHeaders: Record<string, string> = {
      Accept: "application/json",
    };

    // Step 1: Login if credentials provided
    if (username && password) {
      try {
        const authRes = await $fetch.raw(`${urlStr}/api/auth`, {
          method: "POST",
          body: { username, password },
          headers: { "Content-Type": "application/json" },
          timeout: 120000,
          // ignoreResponseError to handle status codes manually if needed
        });

        // 1. Extract Cookie if available
        const setCookie = authRes.headers.get("set-cookie");
        if (setCookie) {
          // Multiple cookies might be joined by comma, just pass the whole string
          authHeaders["Cookie"] = setCookie;
        }

        // 2. Extract Token from body if available (fallback)
        const authData: any = authRes._data;
        if (authData && authData.token) {
          authHeaders["Authorization"] = `Bearer ${authData.token}`;
        }

        // 3. Fallback to basic auth just in case the /api/auth endpoint is a dummy
        if (!setCookie && !(authData && authData.token)) {
          authHeaders["Authorization"] =
            "Basic " +
            Buffer.from(`${username}:${password}`).toString("base64");
        }
      } catch (err: any) {
        if (err.status === 401) {
          throw createError({
            statusCode: 401,
            statusMessage: "Login failed: Invalid credentials",
          });
        }
        // If /api/auth returns 404, maybe the device doesn't have this endpoint. We can continue and let the next request fail.
        if (err.status !== 404) {
          throw err;
        }
      }
    }

    let isBusy = false;

    // Step 2: Update module info
    try {
      await $fetch(`${urlStr}/api/device/mobile`, {
        method: "POST",
        body: {},
        headers: authHeaders,
        timeout: 120000,
      });
    } catch (e: any) {
      if (e.response?._data?.result?.messages?.[0]?.code === "E542") {
        isBusy = true;
      }
      console.warn("POST /api/device/mobile failed, ignoring...", e);
    }

    // Step 3: Update SIM info for module 0
    try {
      await $fetch(`${urlStr}/api/device/mobile/sim`, {
        method: "POST",
        body: { "module-number": 0 },
        headers: authHeaders,
        timeout: 120000,
      });
    } catch (e: any) {
      if (e.response?._data?.result?.messages?.[0]?.code === "E542") {
        isBusy = true;
      }
      console.warn("POST /api/device/mobile/sim failed, ignoring...", e);
    }

    // Step 4: Fetch the refreshed mobile info
    const res: any = await $fetch(`${urlStr}/api/device/mobile`, {
      method: "GET",
      headers: authHeaders,
      timeout: 120000,
    });

    return { ...res, isBusy };
  } catch (err: any) {
    if (err.status === 401) {
      throw createError({ statusCode: 401, statusMessage: "Unauthorized" });
    }
    throw createError({
      statusCode: 500,
      statusMessage: err.message || "Failed to communicate with device",
    });
  } finally {
    // Restore TLS setting
    if (originalTlsConfig !== undefined) {
      process.env.NODE_TLS_REJECT_UNAUTHORIZED = originalTlsConfig;
    } else {
      delete process.env.NODE_TLS_REJECT_UNAUTHORIZED;
    }
  }
});

import { $fetch } from "ofetch";

export default defineEventHandler(async (event) => {
  const body = await readBody(event);
  const { baseUrl, username, password } = body;

  const urlStr = baseUrl.startsWith("http") ? baseUrl : `https://${baseUrl}`;

  const originalTlsConfig = process.env.NODE_TLS_REJECT_UNAUTHORIZED;
  process.env.NODE_TLS_REJECT_UNAUTHORIZED = "0";

  try {
    let authHeaders: Record<string, string> = {
      Accept: "application/json",
    };

    if (username && password) {
      try {
        const authRes = await $fetch.raw(`${urlStr}/api/auth`, {
          method: "POST",
          body: { username, password },
          headers: { "Content-Type": "application/json" },
          timeout: 120000,
        });

        const setCookie = authRes.headers.get("set-cookie");
        if (setCookie) {
          authHeaders["Cookie"] = setCookie;
        }

        const authData: any = authRes._data;
        if (authData && authData.token) {
          authHeaders["Authorization"] = `Bearer ${authData.token}`;
        }

        if (!setCookie && !(authData && authData.token)) {
          authHeaders["Authorization"] =
            "Basic " +
            Buffer.from(`${username}:${password}`).toString("base64");
        }
      } catch (err: any) {
        if (err.status === 401) {
          throw createError({
            statusCode: 401,
            statusMessage: "Login failed: Invalid credentials",
          });
        }
        if (err.status !== 404) {
          throw err;
        }
      }
    }

    const res = await $fetch(`${urlStr}/api/device/poe`, {
      method: "GET",
      headers: authHeaders,
      timeout: 120000,
    });

    return res;
  } catch (err: any) {
    if (err.status === 401) {
      throw createError({ statusCode: 401, statusMessage: "Unauthorized" });
    }
    throw createError({
      statusCode: 500,
      statusMessage: err.message || "Failed to communicate with device",
    });
  } finally {
    if (originalTlsConfig !== undefined) {
      process.env.NODE_TLS_REJECT_UNAUTHORIZED = originalTlsConfig;
    } else {
      delete process.env.NODE_TLS_REJECT_UNAUTHORIZED;
    }
  }
});

import { defineEventHandler, readBody, createError } from "h3";
import { z } from "zod";

const bodySchema = z.object({
  targetUrl: z.string().url("Invalid target URL"),
  defaultPassword: z.string().default("yoko1234"),
});

export default defineEventHandler(async (event) => {
  const body = await readBody(event);
  const result = bodySchema.safeParse(body);

  if (!result.success) {
    throw createError({
      statusCode: 400,
      statusMessage: "Invalid input parameters",
      data: result.error.format(),
    });
  }

  const { targetUrl, defaultPassword } = result.data;
  const apiUrl = new URL("/api/on_first_startup", targetUrl).toString();

  try {
    // 1. Check startup state
    const getResponse = await $fetch<any>(apiUrl, {
      method: "GET",
      timeout: 10000,
      // @ts-ignore
      rejectUnauthorized: false,
    });

    const messages = getResponse?.result?.messages || [];
    const needsSetup = messages.some((m: any) => m.code === "E210");

    if (needsSetup) {
      // 2. Register password
      const postResponse = await $fetch<any>(apiUrl, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: { password: defaultPassword },
        timeout: 15000,
        // @ts-ignore
        rejectUnauthorized: false,
      });

      return {
        initialized: true,
        actionTaken: "password_set",
        message:
          "Device was uninitialized. Admin password has been set automatically.",
        detail: postResponse,
      };
    } else {
      return {
        initialized: true,
        actionTaken: "none",
        message: "Device is already initialized.",
      };
    }
  } catch (error: any) {
    console.error("Startup check error:", error);
    // If it's a 404 or 401, it might mean the device is already fully initialized and the endpoint is protected/gone.
    // We treat errors (like 401/404) as "already setup" unless it's a hard timeout/network error.
    if (
      error.statusCode === 401 ||
      error.statusCode === 404 ||
      error.statusCode === 403
    ) {
      return {
        initialized: true,
        actionTaken: "none",
        message: "Device is likely initialized (endpoint blocked).",
      };
    }

    throw createError({
      statusCode: error.statusCode || 500,
      statusMessage:
        error.statusMessage || "Failed to check device startup state",
    });
  }
});

import { exec } from "node:child_process";
import { promisify } from "node:util";
import path from "node:path";
import { getSettings } from "../../utils/settingsManager";

const execAsync = promisify(exec);

export default defineEventHandler(async (event) => {
  const query = getQuery(event);
  let type = (query.type as string) || "release";
  if (type === "playground") {
    type = "release";
  }
  const targetPath = query.targetPath as string;

  if (!targetPath) {
    throw createError({
      statusCode: 400,
      statusMessage: "targetPath is required",
    });
  }

  const e2eDir = getSettings().e2ePath;
  const fullTargetPath = `playwright/tests/${type}/${targetPath}`;

  try {
    const isWindows = process.platform === "win32";
    // Run playwright list command on the specific target
    const cmd = isWindows
      ? `npx.cmd playwright test ${fullTargetPath} --list --reporter=json`
      : `npx playwright test ${fullTargetPath} --list --reporter=json`;

    const { stdout } = await execAsync(cmd, { cwd: e2eDir });

    const configIndex = stdout.indexOf('"config":');
    if (configIndex === -1) {
      console.error('Could not find "config": in output');
      return {};
    }

    const jsonStart = stdout.lastIndexOf("{", configIndex);
    if (jsonStart === -1) {
      return {};
    }

    let report;
    try {
      report = JSON.parse(stdout.substring(jsonStart));
    } catch (parseErr: any) {
      throw new Error(`JSON parse error: ${parseErr.message}`);
    }

    const suites = report.suites || [];
    const casesMap: Record<string, string[]> = {};

    const typePrefix = `playwright/tests/${type}/`;
    const typePrefix2 = `${type}/`;

    for (const suite of suites) {
      let relPath = suite.file;

      if (relPath.includes(typePrefix)) {
        relPath = relPath.substring(
          relPath.indexOf(typePrefix) + typePrefix.length,
        );
      } else if (relPath.includes(typePrefix2)) {
        relPath = relPath.substring(
          relPath.indexOf(typePrefix2) + typePrefix2.length,
        );
      }

      relPath = relPath.replace(/\\/g, "/");
      const cases = suite.specs ? suite.specs.map((s: any) => s.title) : [];

      casesMap[relPath] = cases;
    }

    return casesMap;
  } catch (error: any) {
    console.error("Failed to read test cases via playwright:", error);
    throw createError({
      statusCode: 500,
      statusMessage: error.message || String(error),
    });
  }
});

import fs from "node:fs/promises";
import path from "node:path";
import { getSettings } from "../../utils/settingsManager";

export default defineEventHandler(async (event) => {
  const query = getQuery(event);
  let type = (query.type as string) || "release";
  if (type === "playground") {
    type = "release";
  }
  const dirPath = path.join(getSettings().e2ePath, `test-order/${type}`);

  try {
    const files = await fs.readdir(dirPath);
    const jsonFiles = files.filter((f) => f.endsWith(".json"));

    const results = [];
    for (const file of jsonFiles) {
      const content = await fs.readFile(path.join(dirPath, file), "utf-8");
      try {
        const tests = JSON.parse(content);
        results.push({
          name: file,
          tests: Array.isArray(tests) ? tests : [],
        });
      } catch (_e: unknown) {
        console.error(`Invalid JSON in ${file}`);
      }
    }

    return results;
  } catch (e: unknown) {
    const error = e as any;
    if ((error as { response?: { status?: number }, statusCode?: number, message?: string, statusMessage?: string, code?: string }).code === "ENOENT") {
      return []; // No test orders yet
    }
    console.error("Failed to read test orders:", error);
    throw createError({
      statusCode: 500,
      statusMessage: "Failed to read test orders",
    });
  }
});

import fs from "node:fs/promises";
import path from "node:path";
import { existsSync } from "node:fs";
import type { SessionMeta } from "../../shared/types";

const SESSIONS_DIR = process.env.APP_DATA_PATH
  ? path.join(process.env.APP_DATA_PATH, "sessions")
  : path.resolve(process.cwd(), "sessions");

export const getLiveProgress = async (
  sessionId: string,
): Promise<SessionMeta | null> => {
  const logsDir = path.join(SESSIONS_DIR, sessionId, "logs");

  if (!existsSync(logsDir)) {
    return null;
  }

  // Find the latest e2e log file
  const files = await fs.readdir(logsDir);
  const e2eLogs = files
    .filter((f) => f.startsWith("e2e") && f.endsWith(".log"))
    .sort()
    .reverse();

  if (e2eLogs.length === 0) {
    return null;
  }

  const e2eLogPath = path.join(logsDir, e2eLogs[0]!);

  try {
    const logs = await fs.readFile(e2eLogPath, "utf-8");
    const lines = logs.split("\n");

    type InnerTest = {
      name: string;
      status: "running" | "PASSED" | "FAILED" | "SKIPPED";
    };
    type Spec = {
      path: string;
      status: "waiting" | "running" | "passed" | "failed";
      innerTests: InnerTest[];
    };

    const queuedSpecs: Spec[] = [];
    let parsingHeader = false;

    for (const line of lines) {
      const cleanLine = line
        .replace(/\x1B(?:\[[0-9;]*[a-zA-Z]|\].*?\x07|\].*?\x1B\\)/g, "")
        .trim();

      if (
        cleanLine === "--- Executing Playwright Tests in Order ---" ||
        cleanLine.startsWith("Failed tests to rerun:")
      ) {
        parsingHeader = true;
        queuedSpecs.length = 0; // Clear array
        continue;
      }

      if (
        cleanLine.startsWith("-------------------------------------------") ||
        (parsingHeader && cleanLine === "")
      ) {
        parsingHeader = false;
        continue;
      }

      if (parsingHeader) {
        const match = cleanLine.match(/^(\d+)\.\s+(.*\.spec\.ts)$/);
        if (match) {
          queuedSpecs.push({
            path: match[2]!,
            status: "waiting",
            innerTests: [],
          });
          continue;
        }

        const matchRerun = cleanLine.match(
          /-\s+\w+:\s+.*\((.*\.spec\.ts):\d+\)/,
        );
        if (matchRerun) {
          const specPath = matchRerun[1]!;
          if (!queuedSpecs.find((s) => s.path === specPath)) {
            queuedSpecs.push({
              path: specPath,
              status: "waiting",
              innerTests: [],
            });
          }
          continue;
        }
      }

      const execMatch = cleanLine.match(
        /^\[(\d+)\/(\d+)\] Executing:\s+(.*?\.spec\.ts)(?::\d+)?$/,
      );
      if (execMatch) {
        const index = parseInt(execMatch[1]!) - 1;
        if (queuedSpecs[index]) {
          queuedSpecs[index].status = "running";
        } else {
          queuedSpecs.push({
            path: execMatch[3]!,
            status: "running",
            innerTests: [],
          });
        }
        continue;
      }

      const testStartMatch = cleanLine.match(
        /^\[.*?\] TEST START (.*?):\s+(.*)$/,
      );
      if (testStartMatch) {
        const activeSpec = queuedSpecs.find((s) => s.status === "running");
        if (activeSpec) {
          const testName = testStartMatch[2]!.trim();
          const existing = activeSpec.innerTests.find(
            (t) => t.name === testName,
          );
          if (existing) {
            existing.status = "running";
          } else {
            activeSpec.innerTests.push({
              name: testName,
              status: "running",
            });
          }
        }
        continue;
      }

      const testEndMatch = cleanLine.match(
        /^\[.*?\] TEST END status=(.*?)\s+duration=(.*)$/,
      );
      if (testEndMatch) {
        const activeSpec = queuedSpecs.find((s) => s.status === "running");
        if (activeSpec && activeSpec.innerTests.length > 0) {
          const runningTest = activeSpec.innerTests
            .slice()
            .reverse()
            .find((t) => t.status === "running");
          if (runningTest) {
            runningTest.status = testEndMatch[1]!.trim() as any;
          }
        }
        continue;
      }

      const runFinishedMatch = cleanLine.match(
        /^\[.*?\] Run finished: status=(.*?)\s+/,
      );
      if (runFinishedMatch) {
        const activeSpec = queuedSpecs.find((s) => s.status === "running");
        if (activeSpec) {
          activeSpec.status =
            runFinishedMatch[1]!.trim() === "PASSED" ? "passed" : "failed";
        }
      }
    }

    let passed = 0;
    let failed = 0;
    let skipped = 0;

    for (const spec of queuedSpecs) {
      for (const test of spec.innerTests) {
        if (test.status === "PASSED") passed++;
        else if (test.status === "FAILED") failed++;
        else if (test.status === "SKIPPED") skipped++;
      }
    }

    const completedSpecs = queuedSpecs.filter(
      (s) => s.status === "passed" || s.status === "failed",
    ).length;

    return {
      testCounts: { passed, failed, skipped },
      specCounts: { completed: completedSpecs, total: queuedSpecs.length },
    };
  } catch (err) {
    console.error(`Failed to parse live progress for ${sessionId}:`, err);
    return null;
  }
};

import path from "node:path";
import fs from "node:fs";
import type { Session } from "../../shared/types";
import { getSettings } from "./settingsManager";

const _SESSIONS_DIR = process.env.APP_DATA_PATH
  ? path.join(process.env.APP_DATA_PATH, "sessions")
  : path.resolve(process.cwd(), "sessions");
const getReportsDir = () =>
  path.join(getSettings().e2ePath, "test-results/e2e-reports");

export const getAggregatedReport = async (
  sessionId: string,
  session: Session,
) => {
  const sessionCreatedAt = new Date(session.createdAt).getTime();
  const sessionClosedAt = session.closedAt
    ? new Date(session.closedAt).getTime()
    : Infinity;

  // 1. Gather all run directories for this session
  const runDirsList: { path: string; relativePath: string; time: number }[] =
    [];
  const reportsDir = getReportsDir();

  if (fs.existsSync(reportsDir)) {
    const dateDirs = fs
      .readdirSync(reportsDir, { withFileTypes: true })
      .filter((d) => d.isDirectory());
    for (const dateDir of dateDirs) {
      const level1Path = path.join(reportsDir, dateDir.name);
      let expectedPrefix = "test-";
      if (session.board && session.testType !== "playground") {
        let dt = session.deviceType;
        if (session.board === "AR10" && session.deviceType === "Normal") {
          dt = "";
        }
        expectedPrefix = dt
          ? `test-${session.board}-${dt}-`
          : `test-${session.board}-`;
      }

      const runDirs = fs
        .readdirSync(level1Path, { withFileTypes: true })
        .filter((d) => {
          if (!d.isDirectory()) return false;
          if (!d.name.startsWith(expectedPrefix)) return false;

          // Prevent partial match like test-AG10 matching test-AG10-pppoe
          if (session.board && session.testType !== "playground") {
            const rest = d.name.slice(expectedPrefix.length);
            if (!/^\d{6}/.test(rest)) return false;
          }

          return true;
        });
      for (const runDir of runDirs) {
        const runPath = path.join(level1Path, runDir.name);
        const stat = fs.statSync(runPath);
        const dirTime = Math.max(stat.mtimeMs, stat.birthtimeMs);
        if (
          dirTime >= sessionCreatedAt - 10000 &&
          dirTime <= sessionClosedAt + 60000
        ) {
          runDirsList.push({
            path: runPath,
            relativePath: `${dateDir.name}/${runDir.name}`,
            time: dirTime,
          });
        }
      }
    }
  }

  // Sort chronologically (oldest first)
  runDirsList.sort((a, b) => a.time - b.time);

  // 2. Aggregate excel.json files
  const testMap = new Map<string, { category: string, page: string, testId: string, model: string, serial: string, date: string, fw: string, history: any[] }>(); // key -> aggregated test object

  let rerunCounter = 0;

  for (let i = 0; i < runDirsList.length; i++) {
    const run = runDirsList[i]!;
    const allDir = path.join(run.path, "all");
    if (!fs.existsSync(allDir)) continue;

    const files = fs.readdirSync(allDir);
    const excelFile = files.find((f) => f.endsWith("-excel.json"));
    if (!excelFile) continue;

    const htmlIndex = path.join(run.path, "html-report", "index.html");
    const hasHtml = fs.existsSync(htmlIndex);
    const htmlReportUrl = hasHtml
      ? `/api/reports/serve/${run.relativePath}/html-report/index.html`
      : null;

    const isRerun = run.relativePath.toLowerCase().includes("rerun");
    let runTypeLabel = "";
    if (isRerun) {
      rerunCounter++;
      runTypeLabel = `Rerun-${rerunCounter}`;
    }

    try {
      const excelData = fs.readFileSync(path.join(allDir, excelFile), "utf-8");
      const data = JSON.parse(excelData);

      if (data && Array.isArray(data.categories)) {
        for (const cat of data.categories) {
          if (Array.isArray(cat.pages)) {
            for (const page of cat.pages) {
              if (Array.isArray(page.tests)) {
                for (const test of page.tests) {
                  const testId = test["test-id"] || "-";
                  const testModel = test["test-device-model"] || "Unknown";
                  // Use category + page + testId + model as unique key to separate test results across boards
                  const key = `${cat.category}|${page.page}|${testId}|${testModel}`;

                  let existing = testMap.get(key);
                  if (!existing) {
                    existing = {
                      category: cat.category,
                      page: page.page,
                      testId: testId,
                      model: testModel,
                      serial: test["test-device-serial"],
                      date: test["test-date"],
                      fw: test["test-fw"],
                      history: [], // Array of { label, result, htmlReportUrl }
                    };
                    testMap.set(key, existing);
                  }

                  // Update latest meta (model, date, etc.)
                  existing.model = test["test-device-model"];
                  existing.serial = test["test-device-serial"];
                  existing.date = test["test-date"];
                  existing.fw = test["test-fw"];

                  const rawResult = test.result || "-";
                  let status = "Failed";
                  if (rawResult.toLowerCase().includes("pass"))
                    status = "Passed";
                  else if (rawResult.toLowerCase().includes("skip"))
                    status = "Skipped";

                  const pwTestId = test["playwright-test-id"] || "";
                  const specificHtmlReportUrl =
                    hasHtml && pwTestId
                      ? `${htmlReportUrl}#?testId=${pwTestId}`
                      : htmlReportUrl;

                  existing.history.push({
                    label: runTypeLabel,
                    result: rawResult,
                    status: status,
                    htmlReportUrl: specificHtmlReportUrl,
                  });
                }
              }
            }
          }
        }
      }
    } catch (e) {
      console.error("Failed to parse excel file for aggregation", e);
    }
  }

  // 3. Rebuild aggregated excel.json format
  const aggregatedCategories = new Map<string, Map<string, unknown[]>>();

  let passedCount = 0;
  let failedCount = 0;
  let skippedCount = 0;
  let _totalCount = 0;

  for (const test of testMap.values()) {
    const pages =
      aggregatedCategories.get(test.category) ?? new Map<string, unknown[]>();
    const tests = pages.get(test.page) ?? [];

    // Convert to ExcelTest format but with history array
    tests.push({
      "test-id": test.testId,
      "test-device-model": test.model,
      "test-device-serial": test.serial,
      "test-date": test.date,
      "test-fw": test.fw,
      history: test.history,
      latest_result:
        test.history.length > 0
          ? (test.history[test.history.length - 1] as any).result
          : "-",
      latest_status:
        test.history.length > 0
          ? (test.history[test.history.length - 1] as any).status
          : "Failed",
    });

    pages.set(test.page, tests);
    aggregatedCategories.set(test.category, pages);

    // Compute stats based on latest status
    _totalCount++;
    const latestStatus =
      test.history.length > 0
        ? (test.history[test.history.length - 1] as any).status
        : "Failed";
    if (latestStatus === "Passed") passedCount++;
    else if (latestStatus === "Failed") failedCount++;
    else skippedCount++;
  }

  const finalCategories = [];
  for (const [catName, pagesMap] of aggregatedCategories.entries()) {
    const pagesList = [];
    for (const [pageName, tests] of pagesMap.entries()) {
      pagesList.push({
        page: pageName,
        tests: tests,
      });
    }
    finalCategories.push({
      category: catName,
      pages: pagesList,
    });
  }

  return {
    categories: finalCategories,
    // Add meta stats for any future use, but keep structure compatible with excel.json
    _meta: {
      failed: failedCount,
      testCounts: {
        passed: passedCount,
        failed: failedCount,
        skipped: skippedCount,
      },
      specCounts: {
        completed: 0, // Not explicitly tracked in excel.json, but could be derived
        total: 0,
      },
    },
  };
};
